#include <stdio.h>
#include <stdlib.h>

void ft_rev_int_tab(int *tab, int size);

int main(int argc, char **argv)
{
    int size;
    int tab[64];
    int i;

    size = atoi(argv[1]);
    tab[0] = 0;
    i = 0;
    while (i < size && i + 2 < argc)
    {
        tab[i] = atoi(argv[2 + i]);
        i++;
    }
    ft_rev_int_tab(tab, size);
    i = 0;
    while (i < size)
    {
        if (i > 0)
            printf(" ");
        printf("%d", tab[i]);
        i++;
    }
    return (0);
}

